import{_ as e,c as a,a2 as o,o as p}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"交易真的是一个反复试错的过程吗？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易是反复试错理解/入场有信息，但是对结果没有执念.md","filePath":"stock/交易是反复试错理解/入场有信息，但是对结果没有执念.md"}'),r={name:"stock/交易是反复试错理解/入场有信息，但是对结果没有执念.md"};function s(_,t,n,c,i,d){return p(),a("div",null,t[0]||(t[0]=[o('<h1 id="交易真的是一个反复试错的过程吗" tabindex="-1">交易真的是一个反复试错的过程吗？ <a class="header-anchor" href="#交易真的是一个反复试错的过程吗" aria-label="Permalink to &quot;交易真的是一个反复试错的过程吗？&quot;">​</a></h1><p>如果你有这种想法，那离成功也许只有一步之遥。</p><p>讲一个个人经历。</p><p>几年前我刚开始正式学习解读盘面的时候，当时有一些初级的分析能力，能够解读供应需求如何，应该也算是有点水平吧。</p><p>当时听到一个师姐说，做交易就是试，不仅仅你在试，主力也在试。这话我收藏了，很长一段时间我潜意识里都将它作为信条。</p><p>为什么当时会这么受触动呢？因为那时候刚从确定性到用概率的眼光看市场，也没有很成熟的交易理念和认知，就觉得这话听的特别有道理还有点与众不同。</p><p>但是后来我发现这种心态其实是不适合我的。假如你是用类似海龟战法的方法来赚钱，那的确就是不停的试。</p><p><strong>但像我这种花精力去解读行情，在确定的时候进场，就不能抱着试的心态，而应该是有信心的心态，但是对结果没执念，会跟随市场随时调整看法。</strong></p><p>市场不会每一部都按照你的想法展开，市场展开的方法会有自己的试探。但这和抱着试的心态交易是两回事。</p>',9)]))}const f=e(r,[["render",s]]);export{m as __pageData,f as default};
